var _markdown = "\n\n`CGame.h`\n\n当前区域、关卡、游戏状态。初始化 / 关 RW 一般别从 ASI 硬调。\n\n## 当前区域 [#当前区域]\n\n<Api name=\"currArea / currLevel\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static int& currArea;\n      static int& currLevel;\n      static char (&aDatFile)[32];\n      static unsigned char& bMissionPackGame;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      int area = CGame::currArea; // 0 室外，室内为 area 码\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 能否看见外景 / 水 [#能否看见外景--水]\n\n<Api name=\"CanSeeOutSideFromCurrArea / CanSeeWaterFromCurrArea\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static bool CanSeeOutSideFromCurrArea();\n      static bool CanSeeWaterFromCurrArea();\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      if (CGame::CanSeeOutSideFromCurrArea()) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 游戏状态 [#游戏状态]\n\n<Api name=\"gGameState\">\n  进程大状态（加载中 / 可玩等）。值以逆向 / 头注释为准。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      extern int& gGameState;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // if (gGameState == ...) { 已进入可玩 }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 工作矩阵 [#工作矩阵]\n\n<Api name=\"m_pWorkingMatrix1 / m_pWorkingMatrix2\">\n  临时 RW 矩阵。\n\n  ```cpp\n  static RwMatrix*& m_pWorkingMatrix1;\n  static RwMatrix*& m_pWorkingMatrix2;\n  ```\n</Api>\n\n## 生命周期（只读了解） [#生命周期只读了解]\n\n<Api name=\"Initialise / Process / Shutdown\">\n  引擎内部；ASI 用 Events 挂接。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static bool Initialise(char const* datFile);\n      static void Process();\n      static bool Shutdown();\n      static void TidyUpMemory(bool a1, bool clearD3Dmem);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // 不要在插件里直接 Initialise/Shutdown 整局\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## TXD 槽 [#txd-槽]\n\n<Api name=\"gameTxdSlot\">\n  游戏主 txd 槽。\n\n  ```cpp\n  extern int& gameTxdSlot;\n  ```\n</Api>\n";
